const int ACMA = 524;
const int KAPAMA = 500;
int okumalar[] = {510, 530, 515, 505, 495, 520};
bool yanik = false;

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 6; i++) {
    int v = okumalar[i];
    if (!yanik && v > ACMA) yanik = true;
    if (yanik && v < KAPAMA) yanik = false;
    Serial.print(yanik ? 1 : 0);
  }
}
void loop() {}
```

